{
  "questions": [
    {
      "key_facts": [2, 3, 11],
      "question": "Why are immersion and presence treated as different concerns in virtual reality?",
      "reference_answer": "The two major issues in virtual reality are technological, about generating suitable sensory stimuli, and psychological, about how a user perceives those stimuli. These issues give rise to immersion and presence as central concerns. Immersion corresponds to the technological issue, while presence corresponds to the psychological issue.",
      "concepts": ["immersion", "presence", "technological issue", "psychological issue"]
    },
    {
      "key_facts": [16, 17, 18, 19],
      "question": "How can a virtual reality system provide a high degree of immersion without guaranteeing a high degree of presence?",
      "reference_answer": "Immersion is an objective, measurable description of the degree to which a system projects stimuli. Presence is a subjective psychological state inside the user's mind, with no direct manifestation, so it depends on the user's experience. Immersion can aid or produce presence and increases its potential, but it does not ensure presence.",
      "concepts": ["immersion", "presence"]
    },
    {
      "key_facts": [7, 8],
      "question": "How do display resolution and field of view contribute to different qualities of immersion in a virtual reality system?",
      "reference_answer": "Display resolution affects vividness, because higher resolution increases the energy stimulated in a sensory modality and improves visual perception. Field of view affects surrounding, because a wider field of view makes the visual cues more panoramic than a narrow field of view.",
      "concepts": ["display resolution", "field of view", "vivid", "surrounding"]
    }
  ]
}

