{
  "points": [
    {
      "facts": [1],
      "point": "Augmented reality alters ongoing real-world perception, whereas virtual reality completely replaces the user's sense of reality."
    },
    {
      "facts": [2],
      "point": "A virtual reality system needs no physical object or place, while augmented or mixed reality requires the place to exist."
    },
    {
      "facts": [3],
